"""Exact cubic-seven screening for ``K12 + K12`` in ``H^24``.

The spatial lattice is the Coxeter--Todd lattice squared.  This module has
two deliberately finite conclusions.

* It screens the squarefree support products generated by the inert primes
  ``(2)``, ``(3)``, the ramified prime ``delta=2-theta``, and at most one of
  the three primes over 13, with radical norm at most 351.  The screen is
  complete through Vinberg height 100 after replacing actual spatial
  vectors by the larger set of admissible coefficient Gram matrices.
* For the unique dense lane ``<-2*theta> + K12^2`` it realizes and counts
  the first two packets.  These packets are complete and pairwise acute.

An empty necessary-Gram packet is a proof of emptiness.  A nonempty one is
not silently called realized; realization is proved separately for the first
two packets of the selected lane.
"""

from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from functools import lru_cache
from itertools import combinations, product
from math import isqrt

from coxeter_polytopes.exact.cubic7 import CUBIC7_ONE, THETA7, Cubic7
from coxeter_polytopes.search.cubic7_lambda22 import (
    Lambda22GramType,
    lambda22_integer_gram_minimum_at_least,
    lambda22_rank3_gram_types,
)
from coxeter_polytopes.search.cubic7_root_blocks import _bounded_for_caps
from coxeter_polytopes.search.silver_coxeter_todd_squared import (
    DUAL_DIRECTION,
    K12_GRAM,
    K12_MINIMUM,
    K12_RADICAL_THREE_MINIMUM,
    K12_SHELL_COUNTS,
    k12_basis_audit,
    k12_pair,
)


DELTA7 = 2 - THETA7
P13_GENERATORS = (
    Cubic7(0, -1, 2),
    Cubic7(1, -1, 1),
    Cubic7(1, 0, 1),
)
SCALAR_S = 2 * THETA7 + THETA7**2
CUTTING_HEIGHT = Cubic7(33, 94, 42)
CUTTING_CONTROL = Cubic7(1, 6, 3)
CUTTING_NORM = Cubic7(2)
OLD_WITNESS_SCALE = Fraction(3, 2)
REPLACEMENT_WITNESS_SCALE = Fraction(7, 5)
POST_H33_CUTOFF_HEIGHT = Cubic7(169, 474, 211)
POST_H33_CUTOFF_CONTROL = Cubic7(4, 13, 6)
POST_H33_REPLACEMENT_SCALE = Fraction(11, 8)
POST_H33_THREAT_U = (9, -1, 0, 6, -1, 0, -4, 3, 1, -3, -2, 4)
POST_H33_THREAT_V = (23, -1, 0, 14, -1, 0, -11, 7, 4, -7, -5, 11)
POST_H33_THREAT_W = (10, 0, 0, 6, 0, 0, -5, 3, 2, -3, -2, 5)

# One actual maximizing realization of the second rank-two type at the
# cutting height.  The relation 2U-2V+3W=0 is exact.
CUTTING_U = (4, 0, 0, 2, 0, 0, -2, 1, 1, -1, -1, 2)
CUTTING_V = (10, 0, 0, 2, 0, 0, -5, 1, 4, -1, -4, 5)
CUTTING_W = (4, 0, 0, 0, 0, 0, -2, 0, 2, 0, -2, 2)


LOCAL_NORM_PROOF = (
    "For primitive r=(x,y), q(r) divides 2I(r), with "
    "I(r)=(a*x,(y,K12^2)).  The Smith form of K12^2 is 1^12,3^12. "
    "Away from (2),(3) and the squarefree support of a, primitivity forces "
    "zero norm valuation.  At an odd coefficient prime P the valuation is "
    "zero or one, and the positive case forces y in P*K12^2.  At (3) the "
    "valuation is zero or one and the positive case forces all spatial "
    "pairings to be divisible by 3.  At inert (2), evenness gives valuation "
    "zero or one for odd a and exactly one when v_2(a)=1.  Class number one "
    "and U^+=U^2 give the canonical products used below."
)


@dataclass(frozen=True, slots=True)
class Cubic7K12Seed:
    seed_id: str
    support: tuple[str, ...]
    support_element: Cubic7
    radical_norm: int
    split_prime: Cubic7 | None = None

    @property
    def coefficient(self) -> Cubic7:
        return THETA7 * self.support_element

    @property
    def canonical_mirror_norms(self) -> tuple[Cubic7, ...]:
        odd = [CUBIC7_ONE]
        if "p7" in self.support:
            odd += [value * DELTA7 for value in tuple(odd)]
        if "p13" in self.support:
            if self.split_prime is None:
                raise AssertionError("a split support lost its generator")
            odd += [value * self.split_prime for value in tuple(odd)]
        odd = [value * ternary for value in odd for ternary in (1, 3)]
        dyadic = (2,) if "p2" in self.support else (1, 2)
        return tuple(sorted({value * factor for value in odd for factor in dyadic}))


def _seed_manifest() -> tuple[Cubic7K12Seed, ...]:
    base_atoms = (
        ("p2", Cubic7(2), 8),
        ("p3", Cubic7(3), 27),
        ("p7", DELTA7, 7),
    )
    output = []
    for split_index in (None, 0, 1, 2):
        split = None if split_index is None else P13_GENERATORS[split_index]
        atoms = base_atoms + (() if split is None else (("p13", split, 13),))
        for mask in range(1 << len(atoms)):
            if split is not None and not (mask & (1 << (len(atoms) - 1))):
                continue
            support = tuple(atoms[index][0] for index in range(len(atoms)) if mask & (1 << index))
            radical_norm = 1
            element = CUBIC7_ONE
            for index, (_name, atom, norm) in enumerate(atoms):
                if mask & (1 << index):
                    radical_norm *= norm
                    element *= atom
            if radical_norm > 351:
                continue
            suffix = "unit" if not support else "-".join(support)
            if split_index is not None:
                suffix += f"-r{split_index}"
            output.append(
                Cubic7K12Seed(
                    f"cubic7-H24-K12-squared-{suffix}",
                    support,
                    element,
                    radical_norm,
                    split,
                )
            )
    result = tuple(sorted(output, key=lambda seed: (seed.radical_norm, seed.seed_id)))
    if len(result) != 19 or len({seed.seed_id for seed in result}) != 19:
        raise AssertionError("the finite K12^2 support manifest changed")
    return result


SUPPORTED_K12_SEEDS = _seed_manifest()
TWO_THETA_K12_SEED = next(
    seed for seed in SUPPORTED_K12_SEEDS if seed.support == ("p2",)
)


@dataclass(frozen=True, slots=True, order=True)
class Cubic7K12Control:
    height: Cubic7
    norm: Cubic7
    control: Cubic7
    target: Cubic7


def _divisor(seed: Cubic7K12Seed, norm: Cubic7) -> Cubic7:
    divisor = CUBIC7_ONE
    if "p7" in seed.support and (norm / DELTA7).is_integral:
        divisor *= DELTA7
    if seed.split_prime is not None and (norm / seed.split_prime).is_integral:
        divisor *= seed.split_prime
    return divisor


@lru_cache(maxsize=None)
def cubic7_k12_controls(
    seed: Cubic7K12Seed, height_bound: int
) -> tuple[Cubic7K12Control, ...]:
    if seed not in SUPPORTED_K12_SEEDS or height_bound < 0:
        raise ValueError("unsupported seed or negative height bound")
    coefficient = seed.coefficient
    output: set[Cubic7K12Control] = set()
    for norm in seed.canonical_mirror_norms:
        caps = (
            norm * height_bound / coefficient,
            norm / (-coefficient),
            norm / (-coefficient),
        )
        for control in _bounded_for_caps(caps):
            if control.sign(0) <= 0:
                continue
            if not (2 * coefficient * control / norm).is_integral:
                continue
            target = norm + coefficient * control * control
            if any(target.sign(place) < 0 for place in (1, 2)):
                continue
            height = coefficient * control * control / norm
            if (Cubic7(height_bound) - height).sign(0) < 0:
                continue
            output.add(Cubic7K12Control(height, norm, control, target))
    return tuple(sorted(output))


@lru_cache(maxsize=None)
def cubic7_k12_necessary_gram_types(
    seed: Cubic7K12Seed, level: Cubic7K12Control
) -> tuple[Lambda22GramType, ...]:
    divisor = _divisor(seed, level.norm)
    target = level.target / (divisor * divisor)
    if not target.is_integral:
        return ()
    ternary = (level.norm / 3).is_integral
    if not ternary:
        return lambda22_rank3_gram_types(target, K12_MINIMUM, 1)
    # Every Gram entry in the mod-three pairing radical is divisible by
    # three and its minimum is 12.  Dividing the whole Gram by three is an
    # exact bijection with minimum-four Gram types for target/3.  Applying
    # this before enumeration avoids a needlessly large coefficient box.
    if not (target / 3).is_integral:
        return ()
    scaled = lambda22_rank3_gram_types(target / 3, K12_MINIMUM, 1)
    return tuple(
        Lambda22GramType(
            3 * gram.u_square,
            3 * gram.v_square,
            3 * gram.w_square,
            3 * gram.u_dot_v,
            3 * gram.u_dot_w,
            3 * gram.v_dot_w,
            27 * gram.determinant,
        )
        for gram in scaled
    )


@dataclass(frozen=True, slots=True)
class K12SeedScreen:
    seed: Cubic7K12Seed
    height_bound: int
    controls: tuple[Cubic7K12Control, ...]
    nonempty: tuple[tuple[Cubic7K12Control, tuple[Lambda22GramType, ...]], ...]


@lru_cache(maxsize=None)
def screen_cubic7_k12_seed(
    seed: Cubic7K12Seed, height_bound: int = 100
) -> K12SeedScreen:
    levels = cubic7_k12_controls(seed, height_bound)
    nonempty = tuple(
        (level, types)
        for level in levels
        if (types := cubic7_k12_necessary_gram_types(seed, level))
    )
    return K12SeedScreen(seed, height_bound, levels, nonempty)


@dataclass(frozen=True, slots=True)
class TwoThetaK12Packets:
    first_level: Cubic7K12Control
    first_gram_type: Lambda22GramType
    first_wall_count: int
    first_same_height_maximum: Cubic7
    second_level: Cubic7K12Control
    second_gram_type: Lambda22GramType
    minimal_vectors_per_factor: int
    minimal_neighbors_inner_product_minus_one: int
    second_wall_count: int
    first_second_maximum_bound: Cubic7
    second_same_height_maximum_bound: Cubic7


@dataclass(frozen=True, slots=True)
class CuttingRootAudit:
    height: Cubic7
    control: Cubic7
    norm: Cubic7
    coefficient_gram: tuple[tuple[int, int, int], ...]
    h_pairings: tuple[int, int, int]
    old_witness_pairing: Cubic7
    replacement_witness_pairing: Cubic7
    first_packet_maximum: Cubic7
    second_packet_maximum: Cubic7
    third_packet_maximum: Cubic7
    other_cutting_type_maximum: Cubic7
    same_height_maximum: Cubic7
    other_cutting_type_schur_count: int
    same_height_schur_count: int
    same_height_minimum_gate_count: int


@lru_cache(maxsize=1)
def two_theta_k12_first_two_packets() -> TwoThetaK12Packets:
    """Realize and certify the first two nonempty ``a=2theta`` packets."""

    if not k12_basis_audit():
        raise AssertionError("the inherited exact K12 basis audit failed")
    rows = []
    for level in cubic7_k12_controls(TWO_THETA_K12_SEED, 150):
        types = cubic7_k12_necessary_gram_types(TWO_THETA_K12_SEED, level)
        if types:
            rows.append((level, types))
    if len(rows) < 2 or len(rows[0][1]) != 1 or len(rows[1][1]) != 1:
        raise AssertionError("the first two necessary packets changed")
    first, first_types = rows[0]
    second, second_types = rows[1]
    if (
        first.height,
        first.norm,
        first.control,
        first.target,
        first_types[0].matrix,
    ) != (
        Cubic7(5, 14, 6),
        Cubic7(2),
        Cubic7(1, 2, 1),
        Cubic7(12, 28, 12),
        ((0, 0, 0), (0, 16, 8), (0, 8, 4)),
    ):
        raise AssertionError("the first K12^2 packet changed")
    if (
        second.height,
        second.norm,
        second.control,
        second.target,
        second_types[0].matrix,
    ) != (
        Cubic7(16, 45, 20),
        Cubic7(2),
        Cubic7(1, 4, 2),
        Cubic7(34, 90, 40),
        ((4, 10, 5), (10, 40, 20), (5, 20, 10)),
    ):
        raise AssertionError("the second K12^2 packet changed")

    minimal = K12_SHELL_COUNTS[4]
    neighbors = 160
    first_count = 2 * minimal
    second_count = 2 * minimal * neighbors
    first_same = -2 * THETA7 * first.control**2 + 2 * SCALAR_S**2
    # The following two comparisons exhaust a lattice-independent necessary
    # Gram superset of minimum-four vectors.  The maxima are attained in the
    # corresponding K12 shell (negating/reversing a minimal pair for the
    # second comparison).
    first_second = _first_second_necessary_maximum(first.control, second.control)
    second_same = _second_same_height_necessary_maximum(second.control)
    if (
        first_count,
        second_count,
        first_same,
        first_second,
        second_same,
    ) != (
        1_512,
        241_920,
        Cubic7(-4, -14, -6),
        Cubic7(-3, -7, -3),
        Cubic7(-1),
    ):
        raise AssertionError("the K12^2 packet incidence/acuteness data drifted")
    return TwoThetaK12Packets(
        first,
        first_types[0],
        first_count,
        first_same,
        second,
        second_types[0],
        minimal,
        neighbors,
        second_count,
        first_second,
        second_same,
    )


@lru_cache(maxsize=1)
def _first_second_necessary_maximum(
    first_control: Cubic7, second_control: Cubic7
) -> Cubic7:
    from sympy import Matrix

    maximum: Cubic7 | None = None
    for m_dot_d, m_dot_e in product(range(-4, 5), repeat=2):
        gram = (
            (4, m_dot_d, m_dot_e),
            (m_dot_d, 4, -1),
            (m_dot_e, -1, 4),
        )
        if any(
            Matrix(gram).extract(indices, indices).det() < 0
            for size in range(1, 4)
            for indices in combinations(range(3), size)
        ):
            continue
        if not lambda22_integer_gram_minimum_at_least(gram, 4):
            continue
        spatial = SCALAR_S * (
            SCALAR_S * m_dot_e - (SCALAR_S + 1) * m_dot_d
        )
        value = -2 * THETA7 * first_control * second_control + spatial
        if maximum is None or value > maximum:
            maximum = value
    if maximum is None:
        raise AssertionError("the first/second comparison set became empty")
    return maximum


@lru_cache(maxsize=1)
def _second_same_height_necessary_maximum(control: Cubic7) -> Cubic7:
    from coxeter_polytopes.search.silver_leech import integer_determinant

    maximum: Cubic7 | None = None
    identical = (4, -1, -1, 4)
    for dd, de, ed, ee in product(range(-4, 5), repeat=4):
        if (dd, de, ed, ee) == identical:
            continue
        gram = (
            (4, -1, dd, de),
            (-1, 4, ed, ee),
            (dd, ed, 4, -1),
            (de, ee, -1, 4),
        )
        if any(
            integer_determinant(
                tuple(tuple(gram[i][j] for j in indices) for i in indices)
            ) < 0
            for size in range(1, 5)
            for indices in combinations(range(4), size)
        ):
            continue
        if not lambda22_integer_gram_minimum_at_least(gram, 4):
            continue
        spatial = (
            (SCALAR_S + 1) ** 2 * dd
            - SCALAR_S * (SCALAR_S + 1) * (de + ed)
            + SCALAR_S**2 * ee
        )
        value = -2 * THETA7 * control**2 + spatial
        if maximum is None or value > maximum:
            maximum = value
    if maximum is None:
        raise AssertionError("the second-packet comparison set became empty")
    return maximum


def cutting_root() -> tuple[Cubic7, ...]:
    spatial = tuple(
        Cubic7(u, v, w)
        for u, v, w in zip(CUTTING_U, CUTTING_V, CUTTING_W, strict=True)
    )
    return (CUTTING_CONTROL, *spatial, *(Cubic7(0) for _ in range(12)))


def cubic7_k12_lorentz_pair(
    left: tuple[Cubic7, ...], right: tuple[Cubic7, ...]
) -> Cubic7:
    if len(left) != 25 or len(right) != 25:
        raise ValueError("a K12^2 host vector has rank 25")
    spatial = sum(
        (
            Cubic7(K12_GRAM[i][j])
            * left[1 + offset + i]
            * right[1 + offset + j]
            for offset in (0, 12)
            for i in range(12)
            for j in range(12)
            if K12_GRAM[i][j]
        ),
        start=Cubic7(0),
    )
    return -2 * THETA7 * left[0] * right[0] + spatial


def dual_witness(scale: Fraction) -> tuple[Cubic7, ...]:
    return (
        Cubic7(1),
        *(Cubic7(scale * value) for value in DUAL_DIRECTION),
        *(Cubic7(0) for _ in range(12)),
    )


def dual_witness_norm(scale: Fraction) -> Cubic7:
    return Cubic7(Fraction(4, 3) * scale * scale) - 2 * THETA7


def _rank_two_dual_direction_maximum(
    gram: tuple[int, int, int], relation: str
) -> Cubic7:
    """Maximise the K12 dual direction over a necessary rank-two Gram set."""

    u_square, u_dot_v, v_square = gram
    maximum: Cubic7 | None = None
    u_bound = isqrt(4 * u_square // 3) + 2
    v_bound = isqrt(4 * v_square // 3) + 2
    for h_u in range(-u_bound, u_bound + 1):
        for h_v in range(-v_bound, v_bound + 1):
            if 4 * u_square < 3 * h_u * h_u or 4 * v_square < 3 * h_v * h_v:
                continue
            if 4 * (u_square * v_square - u_dot_v * u_dot_v) < 3 * (
                v_square * h_u * h_u
                - 2 * u_dot_v * h_u * h_v
                + u_square * h_v * h_v
            ):
                continue
            if relation == "half":
                if h_v % 2:
                    continue
                value = Cubic7(h_u, h_v, Fraction(h_v, 2))
            elif relation == "thirds":
                if 2 * (h_v - h_u) % 3:
                    continue
                value = Cubic7(h_u, h_v, Fraction(2 * (h_v - h_u), 3))
            else:
                raise ValueError("unknown coefficient relation")
            if maximum is None or value > maximum:
                maximum = value
    if maximum is None:
        raise AssertionError("the dual-direction comparison set became empty")
    return maximum


@lru_cache(maxsize=1)
def cutting_prefix_directional_maxima() -> tuple[Cubic7, ...]:
    """Necessary dual-direction maxima for all five types through H33.

    The final height has two coefficient types.  Retaining both is essential:
    its first type has a larger relaxed maximum than the realized cutter type.
    """

    first = SCALAR_S * 2
    maxima = (
        first,
        _rank_two_dual_direction_maximum((4, 10, 40), "half"),
        _rank_two_dual_direction_maximum((4, 14, 64), "half"),
        _rank_two_dual_direction_maximum((8, 24, 80), "half"),
        _rank_two_dual_direction_maximum((12, 30, 84), "thirds"),
    )
    expected = (
        Cubic7(0, 4, 2),
        Cubic7(2, 6, 3),
        Cubic7(2, 8, 4),
        Cubic7(3, 10, 5),
        Cubic7(4, 10, 4),
    )
    if maxima != expected:
        raise AssertionError("the complete H33 directional maxima changed")
    return maxima


@lru_cache(maxsize=1)
def replacement_prefix_pairing_bounds() -> tuple[Cubic7, ...]:
    controls = (
        Cubic7(1, 2, 1),
        Cubic7(1, 4, 2),
        Cubic7(2, 5, 2),
        CUTTING_CONTROL,
        CUTTING_CONTROL,
    )
    bounds = tuple(
        -2 * THETA7 * control + REPLACEMENT_WITNESS_SCALE * direction
        for control, direction in zip(
            controls, cutting_prefix_directional_maxima(), strict=True
        )
    )
    if any(bound.sign(0) >= 0 for bound in bounds):
        raise AssertionError("the replacement lost strictness in the H33 prefix")
    return bounds


def dual_direction_maximum_for_gram(
    matrix: tuple[tuple[int, int, int], ...]
) -> tuple[Cubic7, tuple[int, int, int], int]:
    """Exact necessary maximum of ``h.y`` for a coefficient Gram type."""

    from sympy import Matrix

    raw = Matrix(matrix)
    rank = raw.rank()
    indices = next(
        selection
        for selection in combinations(range(3), rank)
        if raw.extract(selection, selection).det() != 0
    )
    principal = raw.extract(indices, indices)
    determinant = int(principal.det())
    adjugate = tuple(
        tuple(int(principal.adjugate()[i, j]) for j in range(rank))
        for i in range(rank)
    )
    kernel = tuple(
        tuple(Fraction(int(entry.p), int(entry.q)) for entry in vector)
        for vector in raw.nullspace()
    )
    bounds = tuple(isqrt(4 * matrix[i][i] // 3) + 2 for i in range(3))
    maximum: Cubic7 | None = None
    maximizing = None
    count = 0
    for values in product(*(range(-bound, bound + 1) for bound in bounds)):
        if any(sum(vector[i] * values[i] for i in range(3)) for vector in kernel):
            continue
        selected = tuple(values[i] for i in indices)
        if rank == 3:
            x, y, z = selected
            quadratic = (
                adjugate[0][0] * x * x
                + adjugate[1][1] * y * y
                + adjugate[2][2] * z * z
                + 2 * adjugate[0][1] * x * y
                + 2 * adjugate[0][2] * x * z
                + 2 * adjugate[1][2] * y * z
            )
        elif rank == 2:
            x, y = selected
            quadratic = (
                adjugate[0][0] * x * x
                + adjugate[1][1] * y * y
                + 2 * adjugate[0][1] * x * y
            )
        else:
            quadratic = adjugate[0][0] * selected[0] * selected[0]
        if 3 * quadratic > 4 * determinant:
            continue
        count += 1
        value = Cubic7(*values)
        if maximum is None or value > maximum:
            maximum = value
            maximizing = values
    if maximum is None or maximizing is None:
        raise AssertionError("the augmented dual-direction Gram set is empty")
    return maximum, maximizing, count


@lru_cache(maxsize=1)
def post_h33_necessary_frontier() -> tuple[
    tuple[Cubic7K12Control, tuple[Lambda22GramType, ...]], ...
]:
    """All nonempty necessary levels after H33 through the H169 cutoff."""

    return tuple(
        (level, types)
        for level in cubic7_k12_controls(TWO_THETA_K12_SEED, 1_100)
        if CUTTING_HEIGHT < level.height <= POST_H33_CUTOFF_HEIGHT
        and (types := cubic7_k12_necessary_gram_types(TWO_THETA_K12_SEED, level))
    )


