def post_h33_directional_audit() -> tuple[dict[str, object], ...]:
    """Typewise 7/5 bounds through H169, including exact shell corrections."""

    shell_corrections = {
        (Cubic7(81, 227, 101), 4): (
            Cubic7(5, 12, 5),
            (5, 12, 5),
            9_797_760,
        ),
        (Cubic7(126, 353, 157), 2): (
            Cubic7(6, 16, 7),
            (6, 16, 7),
            55_520_640,
        ),
        (Cubic7(126, 353, 157), 3): (
            Cubic7(6, 16, 7),
            (6, 16, 7),
            9_797_760,
        ),
        (Cubic7(149, 418, 186), 1): (
            Cubic7(6, 18, 8),
            (6, 18, 8),
            6_940_080,
        ),
        (Cubic7(156, 438, 195), 9): (
            Cubic7(11, 31, 14),
            (11, 31, 14),
            29_393_280,
        ),
        (Cubic7(156, 438, 195), 18): (
            Cubic7(13, 31, 13),
            (13, 31, 13),
            3_265_920,
        ),
        (POST_H33_CUTOFF_HEIGHT, 31): (
            Cubic7(7, 18, 8),
            (7, 18, 8),
            107_775_360,
        ),
        (POST_H33_CUTOFF_HEIGHT, 35): (
            Cubic7(9, 23, 10),
            (9, 23, 10),
            1_693_440,
        ),
    }
    output = []
    for level, types in post_h33_necessary_frontier():
        rows = []
        for index, gram in enumerate(types):
            necessary, necessary_arg, necessary_count = dual_direction_maximum_for_gram(
                gram.matrix
            )
            actual, actual_arg, realization_count = shell_corrections.get(
                (level.height, index), (necessary, necessary_arg, None)
            )
            rows.append(
                {
                    "index": index,
                    "gram": gram.matrix,
                    "necessary_direction": necessary,
                    "necessary_arg": necessary_arg,
                    "necessary_count": necessary_count,
                    "actual_direction": actual,
                    "actual_arg": actual_arg,
                    "shell_realization_count": realization_count,
                    "seven_fifths_bound": (
                        -2 * THETA7 * level.control
                        + REPLACEMENT_WITNESS_SCALE * actual
                    ),
                    "eleven_eighths_bound": (
                        -2 * THETA7 * level.control
                        + POST_H33_REPLACEMENT_SCALE * actual
                    ),
                }
            )
        output.append({"level": level, "types": tuple(rows)})
    if tuple(row["level"].height for row in output) != (
        Cubic7(52, 146, 65),
        Cubic7(64, 180, 80),
        Cubic7(81, 227, 101),
        Cubic7(126, 353, 157),
        Cubic7(149, 418, 186),
        Cubic7(156, 438, 195),
        POST_H33_CUTOFF_HEIGHT,
    ):
        raise AssertionError("the post-H33 necessary chronology changed")
    flat = tuple(item for row in output for item in row["types"])
    if any(item["seven_fifths_bound"].sign(0) >= 0 for item in flat[:-37]):
        raise AssertionError("a realized 7/5 threat appeared before H169")
    h169_positive = tuple(
        item["index"]
        for item in output[-1]["types"]
        if item["seven_fifths_bound"].sign(0) >= 0
    )
    if h169_positive != (35,):
        raise AssertionError("the first realized 7/5 threat changed")
    if any(item["eleven_eighths_bound"].sign(0) >= 0 for item in flat):
        raise AssertionError("the 11/8 replacement lost strictness through H169")
    return tuple(output)


def post_h33_threat_root() -> tuple[Cubic7, ...]:
    spatial = tuple(
        Cubic7(u, v, w)
        for u, v, w in zip(
            POST_H33_THREAT_U,
            POST_H33_THREAT_V,
            POST_H33_THREAT_W,
            strict=True,
        )
    )
    return (
        POST_H33_CUTOFF_CONTROL,
        *spatial,
        *(Cubic7(0) for _ in range(12)),
    )


@lru_cache(maxsize=1)
def post_h33_threat_audit() -> dict[str, object]:
    gram = tuple(
        tuple(int(k12_pair(x, y)) for y in (POST_H33_THREAT_U, POST_H33_THREAT_V, POST_H33_THREAT_W))
        for x in (POST_H33_THREAT_U, POST_H33_THREAT_V, POST_H33_THREAT_W)
    )
    expected = ((66, 162, 69), (162, 406, 175), (69, 175, 76))
    if gram != expected:
        raise AssertionError("the explicit H169 threat Gram changed")
    root = post_h33_threat_root()
    if cubic7_k12_lorentz_pair(root, root) != Cubic7(2):
        raise AssertionError("the H169 threat lost norm two")
    old_pairing = cubic7_k12_lorentz_pair(
        dual_witness(REPLACEMENT_WITNESS_SCALE), root
    )
    replacement_pairing = cubic7_k12_lorentz_pair(
        dual_witness(POST_H33_REPLACEMENT_SCALE), root
    )
    h33_pairing = cubic7_k12_lorentz_pair(cutting_root(), root)
    if (
        old_pairing != Cubic7(Fraction(3, 5), Fraction(1, 5))
        or replacement_pairing
        != Cubic7(Fraction(3, 8), Fraction(-3, 8), Fraction(-1, 4))
        or h33_pairing != Cubic7(-15, -46, -21)
    ):
        raise AssertionError("the H169 threat pairing ledger changed")
    return {
        "gram": gram,
        "h_pairings": (
            POST_H33_THREAT_U[0],
            POST_H33_THREAT_V[0],
            POST_H33_THREAT_W[0],
        ),
        "norm": Cubic7(2),
        "old_pairing": old_pairing,
        "replacement_pairing": replacement_pairing,
        "h33_cutter_pairing": h33_pairing,
    }


@lru_cache(maxsize=1)
def _cutting_same_height_maximum() -> tuple[Cubic7, int, int]:
    """Maximise between distinct roots of the cutting coefficient type.

    Each coefficient triple is generated by a rank-two pair ``U,V`` with
    Gram ``[[12,30],[30,84]]`` and ``W=2(V-U)/3``.  Four integral cross
    entries determine the joint Gram.  The Schur-complement inequalities,
    divisibility relation, and exact integral minimum-four gate exhaust a
    necessary superset.  Its maximum is already strictly negative.
    """

    from coxeter_polytopes.search.cubic7_lambda22 import (
        lambda22_integer_gram_minimum_at_least,
    )

    alpha = Cubic7(1, 0, Fraction(-2, 3))
    beta = Cubic7(0, 1, Fraction(2, 3))
    maximum: Cubic7 | None = None
    schur_count = 0
    minimum_count = 0
    for a in range(-12, 13):
        for c in range(-31, 32):
            r11 = 216 - (14 * a * a - 10 * a * c + 2 * c * c)
            if r11 < 0:
                continue
            for b in range(-31, 32):
                for d in range(-84, 85):
                    r22 = 1512 - (14 * b * b - 10 * b * d + 2 * d * d)
                    if r22 < 0:
                        continue
                    r12 = 540 - (
                        14 * a * b - 5 * (a * d + c * b) + 2 * c * d
                    )
                    if r11 * r22 < r12 * r12:
                        continue
                    if (b - a) % 3 or (d - c) % 3:
                        continue
                    schur_count += 1
                    if (a, b, c, d) == (12, 30, 30, 84):
                        continue
                    gram = (
                        (12, 30, a, b),
                        (30, 84, c, d),
                        (a, c, 12, 30),
                        (b, d, 30, 84),
                    )
                    if not lambda22_integer_gram_minimum_at_least(gram, 4):
                        continue
                    minimum_count += 1
                    spatial = alpha * alpha * a + alpha * beta * (b + c) + beta * beta * d
                    value = -2 * THETA7 * CUTTING_CONTROL**2 + spatial
                    if maximum is None or value > maximum:
                        maximum = value
    if maximum != Cubic7(0, -4, -2):
        raise AssertionError("the cutting same-height maximum changed")
    return maximum, schur_count, minimum_count


@lru_cache(maxsize=1)
def _cutting_other_type_maximum() -> tuple[Cubic7, int]:
    """Compare the cutter with the other necessary type at the same height.

    The comparison retains the full Schur/divisibility superset.  Its maximum
    is already negative, so no realization or minimum-four test is needed.
    """

    alpha = Cubic7(1, 0, Fraction(-2, 3))
    beta = Cubic7(0, 1, Fraction(2, 3))
    delta = Cubic7(0, 1, Fraction(1, 2))
    maximum: Cubic7 | None = None
    count = 0
    left = []
    right = []
    for square, output in ((8, left), (80, right)):
        for a in range(-isqrt(12 * square) - 1, isqrt(12 * square) + 2):
            for c in range(-isqrt(84 * square) - 1, isqrt(84 * square) + 2):
                residual = 18 * square - (14 * a * a - 10 * a * c + 2 * c * c)
                if residual >= 0 and (c - a) % 3 == 0:
                    output.append((a, c, residual))
    for a, c, r11 in left:
        for b, d, r22 in right:
            if b % 2 or d % 2:
                continue
            r12 = 18 * 24 - (
                14 * a * b - 5 * (a * d + c * b) + 2 * c * d
            )
            if r11 * r22 < r12 * r12:
                continue
            count += 1
            spatial = alpha * a + alpha * delta * b + beta * c + beta * delta * d
            value = -2 * THETA7 * CUTTING_CONTROL**2 + spatial
            if maximum is None or value > maximum:
                maximum = value
    if (maximum, count) != (Cubic7(-2, -8, -4), 1_225):
        raise AssertionError("the other H33-type cutter comparison changed")
    return maximum, count


@lru_cache(maxsize=1)
def cutting_root_audit() -> CuttingRootAudit:
    gram = tuple(
        tuple(int(k12_pair(left, right)) for right in (CUTTING_U, CUTTING_V, CUTTING_W))
        for left in (CUTTING_U, CUTTING_V, CUTTING_W)
    )
    expected = ((12, 30, 12), (30, 84, 36), (12, 36, 16))
    if gram != expected or tuple(
        2 * u - 2 * v + 3 * w
        for u, v, w in zip(CUTTING_U, CUTTING_V, CUTTING_W, strict=True)
    ) != (0,) * 12:
        raise AssertionError("the explicit cutting coefficient triple changed")
    root = cutting_root()
    if cubic7_k12_lorentz_pair(root, root) != CUTTING_NORM:
        raise AssertionError("the explicit cutter lost norm two")
    # Norm two makes all spatial reflection coefficients integral; the time
    # coefficient is also integral.  Norm two is squarefree at inert (2), so
    # the root cannot be a nonunit multiple.
    if not (2 * THETA7 * CUTTING_CONTROL).is_integral:
        raise AssertionError("the cutter lost time-line reflection integrality")
    old_pair = cubic7_k12_lorentz_pair(dual_witness(OLD_WITNESS_SCALE), root)
    replacement_pair = cubic7_k12_lorentz_pair(
        dual_witness(REPLACEMENT_WITNESS_SCALE), root
    )
    same, schur_count, minimum_count = _cutting_same_height_maximum()
    other_same, other_schur_count = _cutting_other_type_maximum()
    return CuttingRootAudit(
        CUTTING_HEIGHT,
        CUTTING_CONTROL,
        CUTTING_NORM,
        gram,
        (CUTTING_U[0], CUTTING_V[0], CUTTING_W[0]),
        old_pair,
        replacement_pair,
        Cubic7(0),
        Cubic7(0, -3, -2),
        Cubic7(-4, -8, -3),
        other_same,
        same,
        other_schur_count,
        schur_count,
        minimum_count,
    )


